fn map_publication_inventory_gate_failures(
    inventory_rows: &[MapPublicationInventoryRow],
    atlas_rows: &[MapAtlasRow],
    readiness_rows: &[MapPublicationReadinessRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if inventory_rows.is_empty() {
        failures.push("map publication inventory has no rows".to_string());
    }
    let Some(readiness) = readiness_rows.first() else {
        failures.push("map publication readiness has no rows".to_string());
        return failures;
    };
    if readiness.validation_status != "pass" {
        failures.push(format!(
            "map publication readiness is {}",
            readiness.validation_status
        ));
    }
    if readiness.publication_blocker_count != 0 {
        failures.push(format!(
            "map publication readiness has {} publication blockers",
            readiness.publication_blocker_count
        ));
    }
    if inventory_rows.len() != atlas_rows.len() {
        failures.push(format!(
            "inventory row count {} != atlas row count {}",
            inventory_rows.len(),
            atlas_rows.len()
        ));
    }

    let atlas_by_id = atlas_rows
        .iter()
        .map(|row| (row.map_id.as_str(), row))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut seen_ids = std::collections::BTreeSet::new();
    let required_forbidden = [
        "evidence-valid",
        "sla-valid",
        "transit-ready",
        "upgrade-ready",
        "asset-condition-repaired",
    ];

    for row in inventory_rows {
        if !seen_ids.insert(row.map_id.as_str()) {
            failures.push(format!("{} appears more than once", row.map_id));
        }
        let Some(atlas) = atlas_by_id.get(row.map_id.as_str()) else {
            failures.push(format!("{} is not in map atlas", row.map_id));
            continue;
        };
        if row.map_path != atlas.path {
            failures.push(format!(
                "{} path {} != atlas {}",
                row.map_id, row.map_path, atlas.path
            ));
        }
        if row.map_type != atlas.map_type {
            failures.push(format!(
                "{} type {} != atlas {}",
                row.map_id, row.map_type, atlas.map_type
            ));
        }
        if row.publication_status != "publication-ready-held-claims" {
            failures.push(format!(
                "{} publication status is {}",
                row.map_id, row.publication_status
            ));
        }
        if row.render_gate_status != "pass" || row.validation_status != "pass" {
            failures.push(format!("{} inventory status is not pass", row.map_id));
        }
        if row.readiness_artifact != "data/map-publication-readiness.csv" {
            failures.push(format!("{} points to wrong readiness artifact", row.map_id));
        }
        if split_claim_tokens(&row.held_claims)
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>()
            != split_claim_tokens(&readiness.held_claims)
                .into_iter()
                .collect::<std::collections::BTreeSet<_>>()
        {
            failures.push(format!(
                "{} held claims {} != readiness {}",
                row.map_id, row.held_claims, readiness.held_claims
            ));
        }
        if !row.required_label.contains("held") {
            failures.push(format!(
                "{} label does not identify held claims",
                row.map_id
            ));
        }
        for forbidden in required_forbidden {
            if !split_claim_tokens(&row.not_allowed_claims)
                .iter()
                .any(|claim| *claim == forbidden)
            {
                failures.push(format!("{} does not forbid {}", row.map_id, forbidden));
            }
        }
    }

    for atlas in atlas_rows {
        if !seen_ids.contains(atlas.map_id.as_str()) {
            failures.push(format!(
                "{} missing from publication inventory",
                atlas.map_id
            ));
        }
    }

    failures
}

fn merge_hpms_state_records(
    mut existing: Vec<route_data::HpmsRecord>,
    fetched: Vec<route_data::HpmsRecord>,
    states: &std::collections::BTreeSet<String>,
) -> Vec<route_data::HpmsRecord> {
    existing.retain(|row| !states.contains(&row.state.to_ascii_uppercase()));
    existing.extend(fetched);
    existing.sort_by(|a, b| {
        a.state
            .cmp(&b.state)
            .then_with(|| a.route_id.cmp(&b.route_id))
            .then_with(|| a.aadt.cmp(&b.aadt))
    });
    existing
}

fn parse_hpms_functional_systems(value: &str) -> Result<Vec<u8>> {
    let systems = value
        .split(',')
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .map(|part| {
            part.parse::<u8>()
                .with_context(|| format!("invalid HPMS functional system {part}"))
        })
        .collect::<Result<Vec<_>>>()?;
    if systems.is_empty() {
        anyhow::bail!("at least one HPMS functional system is required");
    }
    let systems = systems
        .into_iter()
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    if systems.iter().any(|system| !(1..=7).contains(system)) {
        anyhow::bail!("HPMS functional systems must be in 1..=7");
    }
    Ok(systems)
}

fn write_hpms_records(path: &Path, records: &[route_data::HpmsRecord]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let tmp = temp_path_for_atomic_write(path);
    let mut writer = csv::Writer::from_path(&tmp)?;
    writer.write_record([
        "STATE",
        "ROUTE_ID",
        "AADT",
        "PCT_TRUCK",
        "LANE_COUNT",
        "IRI",
        "SPEED_LIMIT",
    ])?;
    for record in records {
        writer.write_record(&[
            record.state.clone(),
            record.route_id.clone(),
            record
                .aadt
                .map(|value| value.to_string())
                .unwrap_or_default(),
            record
                .pct_truck
                .map(|value| format!("{value:.4}"))
                .unwrap_or_default(),
            record
                .lane_count
                .map(|value| value.to_string())
                .unwrap_or_default(),
            record
                .iri
                .map(|value| format!("{value:.1}"))
                .unwrap_or_default(),
            record
                .speed_limit
                .map(|value| value.to_string())
                .unwrap_or_default(),
        ])?;
    }
    writer.flush()?;
    drop(writer);
    replace_with_atomic_write(&tmp, path)?;
    Ok(())
}

fn atomic_write_text(path: &Path, text: impl AsRef<str>) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let tmp = temp_path_for_atomic_write(path);
    std::fs::write(&tmp, text.as_ref()).with_context(|| format!("writing {}", tmp.display()))?;
    replace_with_atomic_write(&tmp, path)
}

fn temp_path_for_atomic_write(path: &Path) -> PathBuf {
    let mut file_name = path
        .file_name()
        .map(|value| value.to_os_string())
        .unwrap_or_else(|| "route-cache".into());
    file_name.push(format!(".{}.tmp", std::process::id()));
    path.with_file_name(file_name)
}

fn replace_with_atomic_write(tmp: &Path, path: &Path) -> Result<()> {
    if path.exists() {
        std::fs::remove_file(path)
            .with_context(|| format!("removing previous {}", path.display()))?;
    }
    std::fs::rename(tmp, path)
        .with_context(|| format!("replacing {} with {}", path.display(), tmp.display()))?;
    Ok(())
}

#[derive(Debug, Clone)]
struct ScenarioEdgeCandidate {
    edge_id: u64,
    distance_miles: f64,
    length_miles: f64,
    aadt: Option<u32>,
    lanes: Option<u8>,
    state: String,
    mid_lat: f64,
    mid_lon: f64,
}

fn scenario_edge_candidates(
    graph: &route_network::HighwayGraph,
    route: &str,
    lat: f64,
    lon: f64,
    radius_miles: f64,
    top: usize,
) -> Vec<ScenarioEdgeCandidate> {
    let mut candidates: Vec<ScenarioEdgeCandidate> = graph
        .route_edges(route)
        .iter()
        .filter_map(|&ei| {
            let edge = &graph.graph[ei];
            let (mid_lat, mid_lon) = edge_midpoint(edge)?;
            let distance_miles = haversine_miles(lat, lon, mid_lat, mid_lon);
            (distance_miles <= radius_miles).then(|| ScenarioEdgeCandidate {
                edge_id: edge.id,
                distance_miles,
                length_miles: edge.length_miles,
                aadt: edge.aadt,
                lanes: edge.lane_count,
                state: edge.state.clone(),
                mid_lat,
                mid_lon,
            })
        })
        .collect();

    candidates.sort_by(|a, b| {
        a.distance_miles
            .partial_cmp(&b.distance_miles)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| a.edge_id.cmp(&b.edge_id))
    });
    candidates.truncate(top);
    candidates
}

fn edge_midpoint(edge: &route_network::HighwayEdge) -> Option<(f64, f64)> {
    let coords = edge.geometry.0.as_slice();
    if coords.is_empty() {
        return None;
    }
    let idx = coords.len() / 2;
    let coord = coords[idx];
    Some((coord.y, coord.x))
}

fn haversine_miles(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
    let r = 3958.8_f64;
    let dlat = (lat2 - lat1).to_radians();
    let dlon = (lon2 - lon1).to_radians();
    let a = (dlat / 2.0).sin().powi(2)
        + lat1.to_radians().cos() * lat2.to_radians().cos() * (dlon / 2.0).sin().powi(2);
    2.0 * r * a.sqrt().asin()
}

#[derive(Debug, Clone, serde::Deserialize)]
struct StandardsProofRow {
    standard_id: String,
    tier: String,
    standard_family: String,
    standard: String,
    outcome: String,
    mechanism: String,
    primary_stressor: String,
    acceptance_gate: String,
    evidence_level: String,
    current_artifact: String,
    blocking_gap: String,
    next_command_or_test: String,
    owner_track: String,
}

fn load_standards_proof_ledger(path: &Path) -> Result<Vec<StandardsProofRow>> {
    let file = std::fs::File::open(path)?;
    parse_standards_proof_ledger(file)
}

fn parse_standards_proof_ledger<R: std::io::Read>(reader: R) -> Result<Vec<StandardsProofRow>> {
    let mut rdr = csv::Reader::from_reader(reader);
    let mut rows = Vec::new();
    for result in rdr.deserialize() {
        rows.push(result?);
    }
    Ok(rows)
}

fn standards_evidence_level_is_allowed(level: &str) -> bool {
    matches!(
        level.trim().to_ascii_lowercase().as_str(),
        "implemented" | "heuristic" | "stub" | "planned" | "deprecated"
    )
}

fn standards_blueprint_gate_failures(rows: &[StandardsProofRow]) -> Vec<&StandardsProofRow> {
    rows.iter()
        .filter(|row| {
            !standards_evidence_level_is_allowed(&row.evidence_level)
                || !row.evidence_level.eq_ignore_ascii_case("Implemented")
                || !row.blocking_gap.trim().is_empty()
        })
        .collect()
}

fn standards_pressure_gate_failures(rows: &[StandardsProofRow]) -> Vec<&StandardsProofRow> {
    rows.iter()
        .filter(|row| !standards_pressure_row_has_contract(row))
        .collect()
}

fn standards_pressure_row_has_contract(row: &StandardsProofRow) -> bool {
    !row.standard_id.trim().is_empty()
        && !row.tier.trim().is_empty()
        && !row.standard_family.trim().is_empty()
        && !row.standard.trim().is_empty()
        && !row.outcome.trim().is_empty()
        && !row.mechanism.trim().is_empty()
        && !row.primary_stressor.trim().is_empty()
        && !row.acceptance_gate.trim().is_empty()
        && standards_evidence_level_is_allowed(&row.evidence_level)
        && !row.current_artifact.trim().is_empty()
        && !row.blocking_gap.trim().is_empty()
        && !row.next_command_or_test.trim().is_empty()
        && !row.owner_track.trim().is_empty()
}

fn print_standards_proof(
    rows: &[StandardsProofRow],
    tier: Option<&str>,
    family: Option<&str>,
    details: bool,
) {
    let filtered: Vec<&StandardsProofRow> = rows
        .iter()
        .filter(|row| {
            tier.map(|t| row.tier.eq_ignore_ascii_case(t))
                .unwrap_or(true)
                && family
                    .map(|f| row.standard_family.eq_ignore_ascii_case(f))
                    .unwrap_or(true)
        })
        .collect();

    println!("route standards-proof");
    println!(
        "  standards: {} shown / {} total",
        filtered.len(),
        rows.len()
    );

    let mut by_level: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for row in &filtered {
        *by_level.entry(row.evidence_level.clone()).or_insert(0) += 1;
    }
    if !by_level.is_empty() {
        let summary = by_level
            .iter()
            .map(|(level, count)| format!("{level}: {count}"))
            .collect::<Vec<_>>()
            .join(", ");
        println!("  evidence: {summary}");
    }
    println!();

    println!(
        "{:<24} {:<4} {:<12} {:<11} {}",
        "Standard", "Tier", "Family", "Evidence", "Blocking gap"
    );
    println!("{}", "-".repeat(110));
    for row in filtered {
        println!(
            "{:<24} {:<4} {:<12} {:<11} {}",
            row.standard_id, row.tier, row.standard_family, row.evidence_level, row.blocking_gap
        );
        if details {
            println!("  standard: {}", row.standard);
            println!("  outcome: {}", row.outcome);
            println!("  mechanism: {}", row.mechanism);
            println!("  stressor: {}", row.primary_stressor);
            println!("  gate: {}", row.acceptance_gate);
            println!("  artifact: {}", row.current_artifact);
            println!("  next: {}", row.next_command_or_test);
            println!("  owner: {}", row.owner_track);
        }
    }
}

#[derive(Debug, Clone, serde::Deserialize)]
struct ForumDocketRow {
    review_id: String,
    artifact: String,
    review_type: String,
    status: String,
    roles: String,
    claim_target: String,
    blocking_question: String,
    next_action: String,
    output_artifact: String,
}

fn load_forum_docket(path: &Path) -> Result<Vec<ForumDocketRow>> {
    let file = std::fs::File::open(path)?;
    parse_forum_docket(file)
}

fn parse_forum_docket<R: std::io::Read>(reader: R) -> Result<Vec<ForumDocketRow>> {
    let mut rdr = csv::Reader::from_reader(reader);
    let mut rows = Vec::new();
    for result in rdr.deserialize() {
        rows.push(result?);
    }
    Ok(rows)
}

fn print_forum_docket(rows: &[ForumDocketRow], blockers: bool, details: bool) {
    let failures = forum_docket_gate_failures(rows);
    let failure_ids = failures
        .iter()
        .filter_map(|failure| failure.split_whitespace().next())
        .collect::<std::collections::HashSet<_>>();
    let filtered = if blockers {
        rows.iter()
            .filter(|row| {
                row.status.eq_ignore_ascii_case("planned")
                    || row.status.eq_ignore_ascii_case("held")
                    || failure_ids.contains(row.review_id.as_str())
            })
            .collect::<Vec<_>>()
    } else {
        rows.iter().collect::<Vec<_>>()
    };

    let mut by_status: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    for row in rows {
        *by_status.entry(row.status.clone()).or_insert(0) += 1;
    }

    println!("route forum");
    println!("  reviews: {} shown / {} total", filtered.len(), rows.len());
    println!("  status: {}", format_count_map(&by_status));
    println!("  gate blockers: {}", failures.len());
    println!();
    println!(
        "{:<18} {:<12} {:<10} {:<30} {}",
        "Review", "Type", "Status", "Artifact", "Question"
    );
    println!("{}", "-".repeat(122));
    for row in filtered {
        println!(
            "{:<18} {:<12} {:<10} {:<30} {}",
            row.review_id,
            row.review_type,
            row.status,
            truncate_for_table(&row.artifact, 30),
            row.blocking_question
        );
        if details {
            println!("  roles: {}", row.roles);
            println!("  claim: {}", row.claim_target);
            println!("  next: {}", row.next_action);
            println!("  output: {}", row.output_artifact);
        }
    }
}

fn forum_docket_gate_failures(rows: &[ForumDocketRow]) -> Vec<String> {
    if rows.is_empty() {
        return vec!["forum docket has no review rows".to_string()];
    }

    rows.iter()
        .filter_map(|row| forum_docket_row_failure(row))
        .collect()
}

fn forum_docket_row_failure(row: &ForumDocketRow) -> Option<String> {
    let review_type = row.review_type.trim().to_ascii_lowercase();
    let status = row.status.trim().to_ascii_lowercase();
    let type_ok = matches!(
        review_type.as_str(),
        "parliament" | "stakeholder" | "editorial" | "panel" | "owner"
    );
    let status_ok = matches!(status.as_str(), "planned" | "complete" | "held");
    let required_filled = !row.review_id.trim().is_empty()
        && !row.artifact.trim().is_empty()
        && !row.roles.trim().is_empty()
        && !row.claim_target.trim().is_empty()
        && !row.blocking_question.trim().is_empty()
        && !row.next_action.trim().is_empty()
        && !row.output_artifact.trim().is_empty();

    if !type_ok || !status_ok || !required_filled {
        Some(format!(
            "{} invalid contract: type={} status={} artifact={} output={}",
            if row.review_id.trim().is_empty() {
                "<missing-review-id>"
            } else {
                row.review_id.as_str()
            },
            row.review_type,
            row.status,
            row.artifact,
            row.output_artifact
        ))
    } else {
        None
    }
}

