fn significant_moment_gate_failures(rows: &[SignificantMomentRow]) -> Vec<String> {
    if rows.is_empty() {
        return vec!["significant moment ledger has no rows".to_string()];
    }

    let mut seen_ids = std::collections::HashSet::new();
    let mut seen_flairs = std::collections::HashSet::new();
    let mut failures = Vec::new();

    for row in rows {
        if let Some(failure) = significant_moment_row_failure(row) {
            failures.push(failure);
        }

        let id = row.moment_id.trim();
        if !id.is_empty() && !seen_ids.insert(id.to_string()) {
            failures.push(format!("{id} duplicate moment_id"));
        }

        let flair = row.flair.trim().to_ascii_lowercase();
        if !flair.is_empty() && !seen_flairs.insert(flair) {
            failures.push(format!("{} duplicate flair '{}'", row.moment_id, row.flair));
        }
    }

    failures
}

fn print_release_manifest(path: &Path, rows: &[ReleaseManifestRow], blockers: bool, details: bool) {
    let failures = release_manifest_gate_failures(rows);
    let failure_paths = failures
        .iter()
        .filter_map(|failure| failure.split_whitespace().next())
        .collect::<std::collections::HashSet<_>>();
    let filtered = if blockers {
        rows.iter()
            .filter(|row| failure_paths.contains(row.artifact_path.as_str()))
            .collect::<Vec<_>>()
    } else {
        rows.iter().collect::<Vec<_>>()
    };

    let mut by_public_status = std::collections::BTreeMap::<String, usize>::new();
    let mut by_release_status = std::collections::BTreeMap::<String, usize>::new();
    for row in rows {
        *by_public_status
            .entry(row.public_status.clone())
            .or_default() += 1;
        *by_release_status
            .entry(row.release_status.clone())
            .or_default() += 1;
    }

    println!("route release-manifest");
    println!("  manifest: {}", path.display());
    println!(
        "  artifacts: {} shown / {} total",
        filtered.len(),
        rows.len()
    );
    println!("  release: {}", format_count_map(&by_release_status));
    println!("  public: {}", format_count_map(&by_public_status));
    println!("  gate blockers: {}", failures.len());
    println!();
    println!(
        "{:<48} {:<18} {:<8} {:<18} {}",
        "Artifact", "Class", "Owner", "Public", "Verification"
    );
    println!("{}", "-".repeat(128));
    for row in filtered {
        println!(
            "{:<48} {:<18} {:<8} {:<18} {}",
            truncate_for_table(&row.artifact_path, 48),
            truncate_for_table(&row.artifact_class, 18),
            row.owner_milepost,
            row.public_status,
            truncate_for_table(&row.verification_command, 36),
        );
        if details {
            println!("  release: {}", row.release_status);
            println!("  notes: {}", row.notes);
        }
    }
}

fn release_manifest_gate_failures(rows: &[ReleaseManifestRow]) -> Vec<String> {
    if rows.is_empty() {
        return vec!["release manifest has no rows".to_string()];
    }
    let allowed_release_status = ["release_candidate", "planned", "held", "retired"];
    let allowed_public_status = ["public", "held_public", "internal", "source_needed"];
    let mut seen_paths = std::collections::HashSet::new();
    let mut failures = Vec::new();

    for row in rows {
        let path = row.artifact_path.trim();
        if path.is_empty()
            || row.artifact_class.trim().is_empty()
            || row.owner_milepost.trim().is_empty()
            || row.release_status.trim().is_empty()
            || row.public_status.trim().is_empty()
            || row.verification_command.trim().is_empty()
            || row.notes.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete release manifest fields",
                if path.is_empty() {
                    "<missing-path>"
                } else {
                    path
                }
            ));
            continue;
        }
        if !seen_paths.insert(path.to_string()) {
            failures.push(format!("{path} duplicate release manifest artifact"));
        }
        if !release_manifest_artifact_exists(path) {
            failures.push(format!("{path} release artifact is missing"));
        }
        if !release_manifest_verification_command_allowed(row) {
            failures.push(format!(
                "{path} has unsupported verification command {}",
                row.verification_command
            ));
        }
        if !row.owner_milepost.starts_with('M') || row.owner_milepost[1..].parse::<u8>().is_err() {
            failures.push(format!(
                "{path} has invalid owner milepost {}",
                row.owner_milepost
            ));
        }
        if !allowed_release_status.contains(&row.release_status.as_str()) {
            failures.push(format!(
                "{path} has invalid release status {}",
                row.release_status
            ));
        }
        if !allowed_public_status.contains(&row.public_status.as_str()) {
            failures.push(format!(
                "{path} has invalid public status {}",
                row.public_status
            ));
        }
        if row.public_status == "public" && row.release_status == "held" {
            failures.push(format!("{path} cannot be public while release-held"));
        }
    }

    for required in [
        "data/release-manifest.csv",
        "docs/SPEC_INDEX.md",
        "data/source-fetch-policy.csv",
        "docs/source-fetch-cache-policy.md",
        "docs/optimizer-artifact-manifest.md",
        "data/tier-optimizer-runs.csv",
    ] {
        if !seen_paths.contains(required) {
            failures.push(format!("missing release manifest row for {required}"));
        }
    }
    if seen_paths.contains("data/tier-optimizer-runs.csv") {
        failures.extend(release_manifest_optimizer_bundle_failures());
    }
    failures
}

fn release_manifest_verification_command_allowed(row: &ReleaseManifestRow) -> bool {
    let command = row.verification_command.trim();
    if command == "manual review" {
        return release_manifest_manual_review_allowed(row);
    }
    if command == "cargo test --workspace" {
        return true;
    }
    if command.starts_with("powershell -ExecutionPolicy Bypass -File ") {
        return true;
    }
    let route_args = command
        .strip_prefix("cargo run -q -p route -- ")
        .or_else(|| command.strip_prefix("route "));
    let Some(route_args) = route_args else {
        return false;
    };
    let parts: Vec<&str> = route_args.split_whitespace().collect();
    if parts.iter().any(|part| part.starts_with("--gate")) {
        return true;
    }
    matches!(
        parts.as_slice(),
        ["score-all"] | ["beck-t1-diagnostics"] | ["gap", "--type", _]
    )
}

fn release_manifest_manual_review_allowed(row: &ReleaseManifestRow) -> bool {
    let path = row.artifact_path.trim();
    let class = row.artifact_class.trim();
    path.starts_with("docs/")
        || path.starts_with("specs/")
        || path == "TRACKER.md"
        || path.ends_with("phase-sequence.csv")
        || class.contains("doc")
        || class.contains("plan")
        || class.contains("review")
        || class.contains("closeout")
        || class.contains("spec")
        || class.contains("standard")
        || class.contains("policy")
        || class.contains("roadmap")
        || class.contains("index")
        || class.contains("status")
        || class.contains("script")
}

fn release_manifest_artifact_exists(path: &str) -> bool {
    repo_relative_artifact_path(path).exists()
}

fn release_manifest_artifact_path(path: &str) -> PathBuf {
    repo_relative_artifact_path(path)
}

fn repo_relative_artifact_path(path: &str) -> PathBuf {
    let direct = std::path::PathBuf::from(path);
    if direct.exists() || direct.is_absolute() {
        direct
    } else {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(path)
    }
}

fn release_manifest_optimizer_bundle_failures() -> Vec<String> {
    let manifest_path = release_manifest_artifact_path("data/tier-optimizer-runs.csv");
    let rows = match load_tier_optimizer_runs(&manifest_path) {
        Ok(rows) => rows,
        Err(error) => {
            return vec![format!(
                "data/tier-optimizer-runs.csv could not be loaded for release coverage: {error}"
            )];
        }
    };
    rows.iter()
        .filter(|row| matches!(row.gate_status.as_str(), "pass" | "held-known"))
        .filter(|row| !release_manifest_artifact_exists(&row.artifact))
        .map(|row| {
            format!(
                "{} optimizer artifact is missing from release coverage bundle",
                row.artifact
            )
        })
        .collect()
}

fn significant_moment_row_failure(row: &SignificantMomentRow) -> Option<String> {
    let id = row.moment_id.trim();
    let required_filled = !id.is_empty()
        && !row.date.trim().is_empty()
        && !row.flair.trim().is_empty()
        && !row.kind.trim().is_empty()
        && !row.summary.trim().is_empty()
        && !row.why_it_mattered.trim().is_empty()
        && !row.primary_artifacts.trim().is_empty()
        && !row.commit.trim().is_empty()
        && !row.next_thread.trim().is_empty();
    let id_ok = id.starts_with("MOM-");
    let date_ok = looks_like_iso_date(row.date.trim());
    let kind_ok = row.kind.trim().ends_with("_breakthrough");
    let commit_ok = looks_like_commit_ref(row.commit.trim());
    let missing_artifacts = missing_moment_artifacts(&row.primary_artifacts);

    if !required_filled
        || !id_ok
        || !date_ok
        || !kind_ok
        || !commit_ok
        || !missing_artifacts.is_empty()
    {
        let artifact_note = if missing_artifacts.is_empty() {
            "none".to_string()
        } else {
            missing_artifacts.join("; ")
        };
        Some(format!(
            "{} invalid moment contract: date={} kind={} commit={} missing_artifacts={}",
            if id.is_empty() {
                "<missing-moment-id>"
            } else {
                id
            },
            row.date,
            row.kind,
            row.commit,
            artifact_note
        ))
    } else {
        None
    }
}

fn looks_like_iso_date(value: &str) -> bool {
    let bytes = value.as_bytes();
    bytes.len() == 10
        && bytes[4] == b'-'
        && bytes[7] == b'-'
        && bytes
            .iter()
            .enumerate()
            .all(|(idx, byte)| idx == 4 || idx == 7 || byte.is_ascii_digit())
}

fn looks_like_commit_ref(value: &str) -> bool {
    (7..=40).contains(&value.len()) && value.chars().all(|ch| ch.is_ascii_hexdigit())
}

fn missing_moment_artifacts(primary_artifacts: &str) -> Vec<String> {
    primary_artifacts
        .split(';')
        .map(str::trim)
        .filter(|artifact| !artifact.is_empty())
        .filter(|artifact| !moment_artifact_exists(artifact))
        .map(str::to_string)
        .collect()
}

fn moment_artifact_exists(artifact: &str) -> bool {
    let path = Path::new(artifact);
    if path.exists() {
        return true;
    }
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join(path)
        .exists()
}

