// `t2_blocker_closure_rows` moved to `t2_blocker_closure_rows.rs`

fn bundle_qualification_effects_by_route(
    bundle_rows: &[NationalSegmentBundleRow],
) -> std::collections::BTreeMap<String, String> {
    let mut effects_by_route =
        std::collections::BTreeMap::<String, std::collections::BTreeSet<String>>::new();
    for row in bundle_rows {
        if row.qualification_effects.trim().is_empty() {
            continue;
        }
        for route in semicolon_values(&row.route_labels) {
            insert_pipe_values(
                effects_by_route
                    .entry(canonical_route_key(&route))
                    .or_default(),
                &row.qualification_effects,
            );
        }
    }
    effects_by_route
        .into_iter()
        .map(|(route, effects)| (route, join_pipe_set(&effects)))
        .collect()
}

fn t2_blocker_bundle_fields(
    registry: &route_network::BundleRegistry,
    route: &str,
) -> (String, String, String) {
    registry
        .by_route_label(route)
        .first()
        .map(|bundle| {
            let (bundle_action, _) =
                route_network::bundle_action(bundle.bundle_status, &bundle.registry_actions);
            (
                bundle.segment_bundle_id.clone(),
                bundle.bundle_status.as_str().to_string(),
                bundle_action.to_string(),
            )
        })
        .unwrap_or_else(|| {
            (
                String::new(),
                "bundle-missing".to_string(),
                "resolve route family or add segment bundle".to_string(),
            )
        })
}

fn write_t2_blocker_closure(path: &Path, rows: &[T2BlockerClosureRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t2_blocker_closure_summary(output: &Path, rows: &[T2BlockerClosureRow]) {
    let mut counts = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *counts.entry(row.blocker_class.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} T2 blocker closure rows to {}",
        rows.len(),
        output.display()
    );
    for (blocker_class, count) in counts {
        println!("  {blocker_class}: {count}");
    }
}

fn t2_blocker_closure_gate_failures(rows: &[T2BlockerClosureRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T2 blocker closure rows emitted".to_string());
        return failures;
    }
    for row in rows {
        if row.route.trim().is_empty()
            || row.bundle_status.trim().is_empty()
            || row.bundle_action.trim().is_empty()
            || row.source_surface.trim().is_empty()
            || row.blocker_class.trim().is_empty()
            || row.blocker_action.trim().is_empty()
            || row.required_evidence.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.optimizer_effect.trim().is_empty()
            || row.closure_status.trim().is_empty()
        {
            failures.push(format!("{} has incomplete blocker closure", row.route));
        }
        if row.bundle_status == "bundle-missing"
            && !matches!(
                row.blocker_class.as_str(),
                "route-family-split"
                    | "relief-contact-repair"
                    | "parent-contact-repair"
                    | "endpoint-exception-upgrade"
            )
        {
            failures.push(format!(
                "{} blocker closure lacks bundle binding for {}",
                row.route, row.blocker_class
            ));
        }
        if !row.qualification_effects.trim().is_empty() && row.segment_bundle_id.trim().is_empty() {
            failures.push(format!(
                "{} carries qualification effects without a segment bundle",
                row.route
            ));
        }
    }
    failures
}

fn load_t2_blocker_closure(path: &Path) -> Result<Vec<T2BlockerClosureRow>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

// `t2_route_family_split_rows` moved to `t2_route_family_split_rows.rs`

fn route_family_split_optimizer_effect(effect: &str, qualification_effects: &str) -> String {
    if qualification_effects.trim().is_empty() {
        return effect.to_string();
    }
    format!("{effect}; qualification_effects={qualification_effects}")
}

fn is_three_digit_interstate(route: &str) -> bool {
    canonical_route_key(route)
        .strip_prefix('I')
        .and_then(|number| number.parse::<u16>().ok())
        .map(|number| number >= 100)
        .unwrap_or_default()
}

fn t2_route_family_split_decision(
    exception: Option<&EndpointExceptionRow>,
) -> (
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
) {
    let Some(exception) = exception else {
        return (
            "add-endpoint-exception-record",
            "blocked",
            "route-family endpoint exception record",
            "data/tier-node-exceptions.csv",
            "blocked from T2 until route family source row exists",
        );
    };

    let endpoint_role = exception.endpoint_role.trim().to_ascii_lowercase();
    let exception_type = exception.exception_type.trim().to_ascii_lowercase();
    if endpoint_role == "graph_endpoint_gap" || exception_type == "missing_graph_geometry" {
        if endpoint_role == "local_access_end" {
            return (
                "split-local-family-or-demote",
                "lower-tier-pressure",
                "metro-specific segment split plus T1/T2 contact proof",
                "data/lower-tier-pressure-witnesses.csv",
                "kept out of T2 until a split segment proves regional service",
            );
        }
        return (
            "split-numbered-family",
            "blocked",
            "represented segment id plus T1/T2 contact proof",
            "data/tier-node-exceptions.csv",
            "blocked from T2 until route family is disambiguated",
        );
    }

    (
        "review-route-family",
        "blocked",
        "route-family split basis",
        "data/tier-node-exceptions.csv",
        "blocked from T2 until route family disposition is explicit",
    )
}

