fn t2_service_diagnostic_queue_gate_failures(rows: &[T2ServiceDiagnosticQueueRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T2 service diagnostic queue rows emitted".to_string());
        return failures;
    }
    if rows.len() == 1 && rows[0].route == "__all_t2_service_diagnostics__" {
        let row = &rows[0];
        if row.diagnostic_status != "service-diagnostic-clear" || row.validation_status != "pass" {
            failures
                .push("service diagnostic clearance row has incomplete clear status".to_string());
        }
        return failures;
    }
    for row in rows {
        if row.route.trim().is_empty() {
            failures.push("service diagnostic queue row missing route".to_string());
        }
        if row.region_id.trim().is_empty() {
            failures.push(format!("{} missing region_id", row.route));
        }
        if row.segment_bundle_id.trim().is_empty() {
            failures.push(format!("{} missing segment_bundle_id", row.route));
        }
        if row.bundle_status != "bundle-ready" {
            failures.push(format!(
                "{} service diagnostic row is not bundle-ready ({})",
                row.route, row.bundle_status
            ));
        }
        if !matches!(
            row.diagnostic_status.as_str(),
            "beck-diagnostic-missing"
                | "beck-diagnostic-review"
                | "route-family-diagnostic-split-needed"
                | "local-relief-map-review"
        ) {
            failures.push(format!(
                "{} unexpected diagnostic_status {}",
                row.route, row.diagnostic_status
            ));
        }
        if row.service_diagnostic_action.trim().is_empty()
            || row.required_artifact.trim().is_empty()
            || row.next_artifact.trim().is_empty()
        {
            failures.push(format!("{} missing diagnostic action artifacts", row.route));
        }
        if !row.qualification_effects.trim().is_empty()
            && !row.optimizer_effect.contains("qualification")
        {
            failures.push(format!(
                "{} diagnostic row drops qualification effects",
                row.route
            ));
        }
        if row.validation_status != "review" {
            failures.push(format!(
                "{} diagnostic queue row must remain review",
                row.route
            ));
        }
    }
    failures
}

fn t2_parallel_service_queue_rows(
    service_rows: &[T2ServiceSelectionRow],
) -> Vec<T2ParallelServiceQueueRow> {
    let mut rows = service_rows
        .iter()
        .filter(|row| {
            row.selection_action == "split-parallel-service" || row.close_parallel_count > 0
        })
        .map(|row| T2ParallelServiceQueueRow {
            route: row.route.clone(),
            region_id: row.region_id.clone(),
            beck_corridor: row.beck_corridor.clone(),
            service_class: row.beck_service_class.clone(),
            close_parallel_count: row.close_parallel_count,
            close_parallel_corridors: row.close_parallel_corridors.clone(),
            selection_action: row.selection_action.clone(),
            selection_basis: row.selection_basis.clone(),
            parallel_action: "review-spacing-or-split-service-before-promotion".to_string(),
            required_artifact: "data/t2-service-selection.csv".to_string(),
            next_artifact: "docs/t2-regional-treatment.md".to_string(),
            optimizer_effect: service_diagnostic_optimizer_effect(
                "keeps close-parallel T2 line visible but below automatic keep/promotion",
                &row.qualification_effects,
            ),
            qualification_effects: row.qualification_effects.clone(),
            validation_status: "review".to_string(),
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| left.route.cmp(&right.route));
    if rows.is_empty() {
        rows.push(T2ParallelServiceQueueRow {
            route: "__all_t2_parallel_services__".to_string(),
            region_id: String::new(),
            beck_corridor: String::new(),
            service_class: String::new(),
            close_parallel_count: 0,
            close_parallel_corridors: String::new(),
            selection_action: "clear".to_string(),
            selection_basis: "no-close-parallel-t2-services".to_string(),
            parallel_action: "no-parallel-service-work-needed".to_string(),
            required_artifact: "data/t2-service-selection.csv".to_string(),
            next_artifact: "data/game/t2-bundle-overlays.csv".to_string(),
            optimizer_effect: "all T2 service rows clear close-parallel review".to_string(),
            qualification_effects:
                "qualification_game_use=default-play|qualification_gate_policy=stop-first"
                    .to_string(),
            validation_status: "pass".to_string(),
        });
    }
    rows
}

