fn t2_bundle_overlay_gate_failures(rows: &[T2BundleOverlayRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T2 bundle overlay rows emitted".to_string());
        return failures;
    }
    for row in rows {
        if row.route.trim().is_empty()
            || row.service_class.trim().is_empty()
            || row.binding_status.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.source_artifacts.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete bundle overlay fields",
                row.route
            ));
        }
        if !matches!(
            row.binding_status.as_str(),
            "bundle-bound"
                | "bundle-bound-review"
                | "bundle-binding-pending"
                | "service-class-overlay-pending"
                | "service-class-held-known"
        ) {
            failures.push(format!(
                "{} has unknown binding status {}",
                row.route, row.binding_status
            ));
        }
        if row.binding_status.starts_with("bundle-bound")
            && !row.segment_bundle_id.starts_with("US.HWYBUNDLE.")
        {
            failures.push(format!(
                "{} claims bundle binding without a bundle id",
                row.route
            ));
        }
        if row.binding_status == "bundle-bound" && row.validation_status != "pass" {
            failures.push(format!("{} bound bundle did not pass", row.route));
        }
        if row.pavement_debt_cost_m < 0.0 {
            failures.push(format!("{} has negative pavement debt cost", row.route));
        }
        if row.pavement_debt_cost_m > 0.0
            && (row.pavement_debt_class.trim().is_empty()
                || row.pavement_debt_basis.trim().is_empty())
        {
            failures.push(format!(
                "{} has pavement debt cost without debt class and basis",
                row.route
            ));
        }
        if !matches!(row.validation_status.as_str(), "pass" | "review") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.route, row.validation_status
            ));
        }
        if matches!(
            row.binding_status.as_str(),
            "bundle-bound" | "bundle-bound-review"
        ) && (row.qualification_map_treatment.trim().is_empty()
            || row.qualification_gate_policy.trim().is_empty()
            || row.qualification_game_use.trim().is_empty())
        {
            failures.push(format!(
                "{} bound overlay missing qualification action semantics",
                row.route
            ));
        }
    }
    failures
}

// `tier_segment_candidate_rows` moved to `tier_segment_candidate_rows.rs`

fn merge_qualification_effects(left: &str, right: &str) -> String {
    let mut values = std::collections::BTreeSet::new();
    for value in left.split('|').chain(right.split('|')).map(str::trim) {
        if !value.is_empty() {
            values.insert(value.to_string());
        }
    }
    join_pipe_set(&values)
}

fn tier_candidate_segment_id(edge: &route_network::HighwayEdge) -> String {
    let first = edge.geometry.0.first().copied();
    let last = edge.geometry.0.last().copied();
    let geometry_key = match (first, last) {
        (Some(first), Some(last)) => {
            format!("{:.5},{:.5}->{:.5},{:.5}", first.x, first.y, last.x, last.y)
        }
        _ => "missing-geometry".to_string(),
    };
    format!(
        "US.HWYSEG.{:016X}",
        stable_segment_hash(&format!(
            "edge|{}|{}|{}|{:.3}",
            edge.route_id, edge.state, geometry_key, edge.length_miles
        ))
    )
}

fn tier_candidate_bundle_id(
    tier: &str,
    region_id: &str,
    route: &str,
    bundle_scope: &str,
) -> String {
    let identity = if bundle_scope.trim().is_empty() {
        format!("candidate-bundle|{tier}|{region_id}|{route}")
    } else {
        format!("candidate-bundle|{tier}|{region_id}|{route}|{bundle_scope}")
    };
    format!("US.HWYBUNDLE.{:016X}", stable_segment_hash(&identity))
}

fn tier_candidate_stitch_group_id(
    tier: &str,
    region_id: &str,
    route: &str,
    bundle_scope: &str,
) -> String {
    let identity = if bundle_scope.trim().is_empty() {
        format!("candidate-stitch|{tier}|{region_id}|{route}")
    } else {
        format!("candidate-stitch|{tier}|{region_id}|{route}|{bundle_scope}")
    };
    format!("US.HWYSTITCH.{:016X}", stable_segment_hash(&identity))
}

fn tier_candidate_aliases(tier: &str, region_id: &str, route: &str, bundle_scope: &str) -> String {
    let mut aliases = vec![
        format!("current-tier:{tier}"),
        format!("current-zone:{region_id}"),
        format!("route:{route}"),
        format!("route-label:{route}"),
        "layer:segment-candidate".to_string(),
    ];
    if !bundle_scope.trim().is_empty() {
        aliases.push(format!("route-family-scope:{bundle_scope}"));
    }
    aliases.join(";")
}

