const PAVEMENT_EVIDENCE_COST_PER_MEMBER_M: f64 = 0.05;
const PAVEMENT_REPAIR_COST_PER_MEMBER_M: f64 = 2.50;

#[derive(Debug, Clone, Default)]
struct PavementDebtBudgetIndex {
    by_bundle: std::collections::HashMap<String, TierPavementDebtBudgetRow>,
    by_route: std::collections::HashMap<String, TierPavementDebtBudgetRollup>,
}

#[derive(Debug, Clone, Default)]
struct TierPavementDebtBudgetRollup {
    total_debt_cost_m: f64,
    debt_classes: std::collections::BTreeSet<String>,
    affected_bundles: std::collections::BTreeSet<String>,
}

fn tier_pavement_debt_budget_rows_with_exclusions(
    gap_rows: &[TierPavementSourceGapRow],
    exclusion_rows: &[TierPavementRouteStateExclusionRow],
    funding_rows: &[TierPavementRepairFundingAcceptanceRow],
) -> Vec<TierPavementDebtBudgetRow> {
    gap_rows
        .iter()
        .filter(|row| !pavement_gap_has_accepted_route_state_exclusion(row, exclusion_rows))
        .filter(|row| !pavement_gap_has_accepted_repair_funding(row, funding_rows))
        .map(|row| {
            let needs_repair = row.blocker_statuses.contains("pavement-repair-required");
            let needs_evidence = row.blocker_statuses.contains("pavement-source-needed");
            let repair_debt_units = if needs_repair { row.blocker_count } else { 0 };
            let evidence_debt_units = if needs_evidence { row.blocker_count } else { 0 };
            let estimated_evidence_cost_m =
                round_cost_m(evidence_debt_units as f64 * PAVEMENT_EVIDENCE_COST_PER_MEMBER_M);
            let estimated_repair_cost_m =
                round_cost_m(repair_debt_units as f64 * PAVEMENT_REPAIR_COST_PER_MEMBER_M);
            let total_debt_cost_m =
                round_cost_m(estimated_evidence_cost_m + estimated_repair_cost_m);
            let debt_class = if needs_repair {
                "repair-debt"
            } else if needs_evidence {
                "evidence-debt"
            } else {
                "classification-debt"
            };
            let next_artifact = if needs_repair {
                "data/tier-pavement-docket.csv"
            } else {
                "data/tier-pavement-acquisition-plan.csv"
            };
            TierPavementDebtBudgetRow {
                tier: row.tier.clone(),
                route: row.route.clone(),
                region_id: row.region_id.clone(),
                segment_bundle_id: row.segment_bundle_id.clone(),
                stitch_group_id: row.stitch_group_id.clone(),
                debt_class: debt_class.to_string(),
                blocked_member_count: row.blocker_count,
                affected_states: row.affected_states.clone(),
                evidence_debt_units,
                repair_debt_units,
                estimated_evidence_cost_m,
                estimated_repair_cost_m,
                total_debt_cost_m,
                budget_basis: format!(
                    "planning proxy: evidence ${:.2}M/member; repair ${:.2}M/member until HPMS/state DOT unit costs replace defaults",
                    PAVEMENT_EVIDENCE_COST_PER_MEMBER_M, PAVEMENT_REPAIR_COST_PER_MEMBER_M
                ),
                optimizer_penalty: format!(
                    "subtract {:.2} budget-cost units from {} service claim until pavement debt closes",
                    total_debt_cost_m, row.segment_bundle_id
                ),
                next_artifact: next_artifact.to_string(),
                validation_status: "review".to_string(),
            }
        })
        .collect()
}

fn pavement_gap_has_accepted_repair_funding(
    gap_row: &TierPavementSourceGapRow,
    funding_rows: &[TierPavementRepairFundingAcceptanceRow],
) -> bool {
    if !gap_row
        .blocker_statuses
        .contains("pavement-repair-required")
    {
        return false;
    }
    let estimated_repair_cost_m =
        round_cost_m(gap_row.blocker_count as f64 * PAVEMENT_REPAIR_COST_PER_MEMBER_M);
    funding_rows.iter().any(|funding| {
        funding.validation_status == "pass"
            && funding.acceptance_status == "accepted-full-cost-repair-funding"
            && funding.tier == gap_row.tier
            && route_display_key(&funding.route) == route_display_key(&gap_row.route)
            && funding.segment_bundle_id == gap_row.segment_bundle_id
            && semicolon_values(&gap_row.affected_states)
                .iter()
                .any(|state| state == &funding.state)
            && funding.committed_amount_m + 1e-6 >= estimated_repair_cost_m
            && funding.covered_repair_cost_m + 1e-6 >= estimated_repair_cost_m
    })
}

fn pavement_gap_has_accepted_route_state_exclusion(
    gap_row: &TierPavementSourceGapRow,
    exclusion_rows: &[TierPavementRouteStateExclusionRow],
) -> bool {
    exclusion_rows.iter().any(|exclusion| {
        exclusion.validation_status == "pass"
            && exclusion.exclusion_status == "route-state-not-supported"
            && exclusion.tier == gap_row.tier
            && route_display_key(&exclusion.route) == route_display_key(&gap_row.route)
            && exclusion.segment_bundle_id == gap_row.segment_bundle_id
            && semicolon_values(&gap_row.affected_states)
                .iter()
                .any(|state| state == &exclusion.state)
    })
}

