fn t2_local_zone_overlay_handoff_gate_failures(
    rows: &[T2LocalZoneOverlayHandoffRow],
    docket_rows: &[T2ServiceClassRepairDocketRow],
) -> Vec<String> {
    let expected = docket_rows
        .iter()
        .filter(|row| row.service_repair_class == "local-zone")
        .map(|row| row.docket_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let mut failures = Vec::new();
    if rows.len() != expected.len() {
        failures.push(format!(
            "local-zone handoff has {} rows but expected {} local-zone repair rows",
            rows.len(),
            expected.len()
        ));
    }
    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.handoff_id.trim().is_empty()
            || row.docket_id.trim().is_empty()
            || row.target_id.trim().is_empty()
            || row.route.trim().is_empty()
            || row.segment_bundle_id.trim().is_empty()
            || row.zone_id.trim().is_empty()
            || row.zone_role.trim().is_empty()
            || row.column_decision.trim().is_empty()
            || row.map_treatment.trim().is_empty()
            || row.handoff_decision.trim().is_empty()
            || row.handoff_reason.trim().is_empty()
            || row.blocks_claims.trim().is_empty()
            || row.required_artifact.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete local-zone handoff fields",
                row.route
            ));
        }
        if !seen.insert(row.docket_id.clone()) {
            failures.push(format!("{} appears more than once", row.docket_id));
        }
        if !expected.contains(row.docket_id.as_str()) {
            failures.push(format!("{} is not a local-zone repair row", row.docket_id));
        }
        if !row.handoff_decision.starts_with("held") {
            failures.push(format!("{} local-zone handoff was promoted", row.route));
        }
        if !row.qualification_effects.trim().is_empty() && !row.handoff_decision.starts_with("held")
        {
            failures.push(format!(
                "{} local-zone handoff carries qualification effects without hold",
                row.route
            ));
        }
        if row.blocks_claims != "game;incident;publication;upgrade" {
            failures.push(format!("{} does not preserve claim blockers", row.route));
        }
        if row.validation_status != "review" {
            failures.push(format!(
                "{} local-zone handoff must remain review",
                row.route
            ));
        }
    }
    for expected_id in expected {
        if !seen.contains(expected_id) {
            failures.push(format!("{expected_id} missing from local-zone handoff"));
        }
    }
    failures
}

fn t2_bundle_readiness_disposition_rows(
    target_rows: &[T2BundleOverlayRepairTargetRow],
) -> Vec<T2BundleReadinessDispositionRow> {
    let mut rows = target_rows
        .iter()
        .filter(|row| {
            matches!(
                row.bundle_status.as_str(),
                "needs-stop-chain" | "needs-stitched-members" | "needs-terminal-stop"
            ) || row.binding_status == "bundle-bound-review"
        })
        .map(|row| {
            let (readiness_class, disposition, action, required_artifact, next_artifact) =
                match row.bundle_status.as_str() {
                    "needs-stop-chain" if row.service_class == "unclassified" => (
                        "stop-chain",
                        "held",
                        "repair-service-class-before-stop-chain-pass",
                        "data/game/t2-service-overlays.csv",
                        "data/national-segment-bundles.csv",
                    ),
                    "needs-stop-chain" => (
                        "stop-chain",
                        "repair-needed",
                        "author-stop-chain-before-bundle-pass",
                        "data/national-segment-registry.csv",
                        "data/national-segment-bundles.csv",
                    ),
                    "needs-stitched-members" => (
                        "stitched-member",
                        "repair-needed",
                        "stitch-member-segments-before-bundle-pass",
                        "data/tier-segment-candidates.csv",
                        "data/national-segment-bundles.csv",
                    ),
                    "needs-terminal-stop" => (
                        "terminal-stop",
                        "repair-needed",
                        "author-terminal-stop-before-bundle-pass",
                        "data/t2-service-selection.csv",
                        "data/national-segment-bundles.csv",
                    ),
                    _ => (
                        "manual-review",
                        "held",
                        "manual-bundle-readiness-review",
                        "data/game/t2-bundle-overlays.csv",
                        "data/t2-bundle-overlay-repair-delta.csv",
                    ),
                };
            T2BundleReadinessDispositionRow {
                disposition_id: format!("T2BUNDLEREADINESS-{}", stable_id_fragment(&row.target_id)),
                target_id: row.target_id.clone(),
                route: row.route.clone(),
                segment_bundle_id: row.segment_bundle_id.clone(),
                bundle_status: row.bundle_status.clone(),
                service_class: row.service_class.clone(),
                readiness_class: readiness_class.to_string(),
                disposition: disposition.to_string(),
                disposition_action: action.to_string(),
                qualification_effects: row.qualification_effects.clone(),
                required_artifact: required_artifact.to_string(),
                next_artifact: next_artifact.to_string(),
                blocks_claims: row.blocks_claims.clone(),
                validation_status: "review".to_string(),
            }
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        left.route
            .cmp(&right.route)
            .then(left.segment_bundle_id.cmp(&right.segment_bundle_id))
    });
    rows
}

