fn t3_lower_tier_feeder_gap_blocker_relief_gate_failures(
    rows: &[T3LowerTierFeederGapBlockerReliefRow],
    acceptance_rows: &[T3LowerTierFeederGapPolicyAcceptanceRow],
) -> Vec<String> {
    let expected = acceptance_rows
        .iter()
        .filter(|row| {
            row.acceptance_decision == "lower-tier-feeder-policy-accepted"
                && row.claim_blocker_delta == 0
                && row.blocker_count_after > 0
        })
        .map(|row| row.acceptance_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let expected_before = acceptance_rows
        .iter()
        .filter(|row| expected.contains(row.acceptance_id.as_str()))
        .map(|row| row.blocker_count_after)
        .sum::<usize>();
    let mut failures = Vec::new();
    if expected.is_empty() {
        failures
            .push("T3 lower-tier feeder blocker relief has no accepted policy rows".to_string());
    }
    if rows.len() != expected.len() {
        failures.push(format!(
            "T3 lower-tier feeder blocker relief has {} rows but expected {}",
            rows.len(),
            expected.len()
        ));
    }
    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.relief_id.trim().is_empty()
            || row.acceptance_id.trim().is_empty()
            || row.policy_id.trim().is_empty()
            || row.route.trim().is_empty()
            || row.zone_id.trim().is_empty()
            || row.score_band.trim().is_empty()
            || row.accepted_map_treatment.trim().is_empty()
            || row.relief_decision.trim().is_empty()
            || row.blocker_claims_before.trim().is_empty()
            || row.ledger_replay_status.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete relief fields",
                row.acceptance_id
            ));
        }
        if !seen.insert(row.acceptance_id.clone()) {
            failures.push(format!("{} appears more than once", row.acceptance_id));
        }
        if !expected.contains(row.acceptance_id.as_str()) {
            failures.push(format!(
                "{} is not an expected acceptance row",
                row.acceptance_id
            ));
        }
        if row.relief_decision != "relief-ready-for-constraint-ledger-replay"
            || row.ledger_replay_status != "pending-optimizer-constraint-ledger-replay"
            || row.validation_status != "review"
        {
            failures.push(format!("{} has invalid relief state", row.acceptance_id));
        }
        if !row.blocker_claims_after.is_empty()
            || row.blocker_count_after != 0
            || row.claim_blocker_delta != -(row.blocker_count_before as isize)
        {
            failures.push(format!(
                "{} did not reduce blockers to zero",
                row.acceptance_id
            ));
        }
    }
    for expected_id in expected {
        if !seen.contains(expected_id) {
            failures.push(format!("{expected_id} missing from blocker relief"));
        }
    }
    let actual_before = rows
        .iter()
        .map(|row| row.blocker_count_before)
        .sum::<usize>();
    let actual_after = rows
        .iter()
        .map(|row| row.blocker_count_after)
        .sum::<usize>();
    if actual_before != expected_before || actual_after != 0 {
        failures.push(format!(
            "T3 lower-tier feeder relief before/after = {actual_before}/{actual_after}, expected {expected_before}/0"
        ));
    }
    failures
}

#[derive(Default)]
struct T1SharedSegmentPolicyBuilder {
    routes: std::collections::BTreeSet<String>,
    source_review_ids: std::collections::BTreeSet<String>,
    blocker_claims: std::collections::BTreeSet<String>,
    blocker_count: usize,
    policy_basis: std::collections::BTreeSet<String>,
    design_treatments: std::collections::BTreeSet<String>,
}

fn t1_shared_segment_map_policy_rows(
    schematic_rows: &[T1SchematicGeometryClaimReviewRow],
) -> Vec<T1SharedSegmentMapPolicyRow> {
    let mut builders = std::collections::BTreeMap::<String, T1SharedSegmentPolicyBuilder>::new();
    for row in schematic_rows.iter().filter(|row| {
        row.policy_action == "resolve-shared-segment-map-policy"
            && row.review_decision == "shared-segment-map-policy-required"
            && row.claim_blocker_delta == 0
    }) {
        let pair = shared_segment_pair_id(&row.route, &row.overlap_corridors);
        let builder = builders.entry(pair).or_default();
        builder.routes.insert(row.route.clone());
        builder
            .routes
            .insert(route_display_key(&row.overlap_corridors));
        builder
            .source_review_ids
            .insert(row.schematic_review_id.clone());
        builder
            .blocker_claims
            .insert(row.blocker_claims_after.clone());
        builder.blocker_count += row.blocker_count_after;
        builder.policy_basis.insert(row.required_policy.clone());
        builder
            .design_treatments
            .insert(row.design_treatment.clone());
    }

    builders
        .into_iter()
        .map(|(route_pair, builder)| {
            let affected_routes = builder.routes.iter().cloned().collect::<Vec<_>>();
            let primary_route = affected_routes.first().cloned().unwrap_or_default();
            let overlap_route = affected_routes.get(1).cloned().unwrap_or_default();
            T1SharedSegmentMapPolicyRow {
                policy_id: format!("T1SHAREDSEG-{}", stable_id_fragment(&route_pair)),
                route_pair,
                primary_route,
                overlap_route,
                affected_routes: affected_routes.join(";"),
                source_review_ids: builder
                    .source_review_ids
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(";"),
                policy_basis: builder
                    .policy_basis
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(";"),
                map_policy_decision: "shared-segment-policy-authored-review".to_string(),
                render_treatment:
                    "represent as interlined trunk service or split at selected transfer stops"
                        .to_string(),
                selector_treatment: "keep both selected promise-spine routes pending acceptance"
                    .to_string(),
                publication_status: "held-pending-policy-acceptance".to_string(),
                blocker_claims_before: builder
                    .blocker_claims
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(";"),
                blocker_claims_after: builder
                    .blocker_claims
                    .iter()
                    .cloned()
                    .collect::<Vec<_>>()
                    .join(";"),
                blocker_count_before: builder.blocker_count,
                blocker_count_after: builder.blocker_count,
                claim_blocker_delta: 0,
                next_artifact: "data/t1-shared-segment-policy-acceptance.csv".to_string(),
                validation_status: "review".to_string(),
            }
        })
        .collect()
}

fn route_display_key(route: &str) -> String {
    route.trim().replace('-', "")
}

fn shared_segment_pair_id(route: &str, overlap_route: &str) -> String {
    let mut routes = [route_display_key(route), route_display_key(overlap_route)];
    routes.sort();
    routes.join("-")
}

