fn t1_schematic_geometry_blocker_relief_gate_failures(
    rows: &[T1SchematicGeometryBlockerReliefRow],
    acceptance_rows: &[T1SharedSegmentPolicyAcceptanceRow],
) -> Vec<String> {
    let expected = acceptance_rows
        .iter()
        .filter(|row| {
            row.acceptance_status == "accepted-policy-ready-for-relief-replay"
                && row.publication_status_after == "held-pending-blocker-relief-replay"
                && row.claim_blocker_delta == 0
        })
        .map(|row| row.acceptance_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();
    let expected_before = acceptance_rows
        .iter()
        .filter(|row| expected.contains(row.acceptance_id.as_str()))
        .map(|row| row.blocker_count_after)
        .sum::<usize>();
    let mut failures = Vec::new();
    if expected.is_empty() {
        failures
            .push("T1 schematic geometry blocker relief has no accepted policy rows".to_string());
    }
    if rows.len() != expected.len() {
        failures.push(format!(
            "T1 schematic geometry blocker relief has {} rows but expected {}",
            rows.len(),
            expected.len()
        ));
    }
    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.relief_id.trim().is_empty()
            || row.acceptance_id.trim().is_empty()
            || row.policy_id.trim().is_empty()
            || row.route_pair.trim().is_empty()
            || row.affected_routes.trim().is_empty()
            || row.accepted_render_treatment.trim().is_empty()
            || row.relief_decision.trim().is_empty()
            || row.blocker_claims_before.trim().is_empty()
            || row.ledger_replay_status.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete relief fields",
                row.acceptance_id
            ));
        }
        if !seen.insert(row.acceptance_id.clone()) {
            failures.push(format!("{} appears more than once", row.acceptance_id));
        }
        if !expected.contains(row.acceptance_id.as_str()) {
            failures.push(format!(
                "{} is not an expected acceptance row",
                row.acceptance_id
            ));
        }
        if row.relief_decision != "relief-ready-for-constraint-ledger-replay"
            || row.ledger_replay_status != "pending-optimizer-constraint-ledger-replay"
            || row.validation_status != "review"
        {
            failures.push(format!("{} has invalid relief state", row.acceptance_id));
        }
        if !row.blocker_claims_after.is_empty()
            || row.blocker_count_after != 0
            || row.claim_blocker_delta != -(row.blocker_count_before as isize)
        {
            failures.push(format!(
                "{} did not reduce blockers to zero",
                row.acceptance_id
            ));
        }
    }
    for expected_id in expected {
        if !seen.contains(expected_id) {
            failures.push(format!("{expected_id} missing from blocker relief"));
        }
    }
    let actual_before = rows
        .iter()
        .map(|row| row.blocker_count_before)
        .sum::<usize>();
    let actual_after = rows
        .iter()
        .map(|row| row.blocker_count_after)
        .sum::<usize>();
    if actual_before != expected_before || actual_after != 0 {
        failures.push(format!(
            "T1 schematic geometry relief before/after = {actual_before}/{actual_after}, expected {expected_before}/0"
        ));
    }
    failures
}

fn pavement_debt_budget_index(rows: &[TierPavementDebtBudgetRow]) -> PavementDebtBudgetIndex {
    let mut index = PavementDebtBudgetIndex::default();
    for row in rows {
        index
            .by_bundle
            .insert(row.segment_bundle_id.clone(), row.clone());
        let route_rollup = index
            .by_route
            .entry(canonical_route_key(&row.route))
            .or_default();
        route_rollup.total_debt_cost_m =
            round_cost_m(route_rollup.total_debt_cost_m + row.total_debt_cost_m);
        route_rollup.debt_classes.insert(row.debt_class.clone());
        route_rollup
            .affected_bundles
            .insert(row.segment_bundle_id.clone());
    }
    index
}

fn pavement_debt_for_candidate(
    route: &str,
    segment_bundle_id: &str,
    index: &PavementDebtBudgetIndex,
) -> (f64, String, String, String) {
    if let Some(row) = index.by_bundle.get(segment_bundle_id) {
        return (
            row.total_debt_cost_m,
            row.debt_class.clone(),
            row.budget_basis.clone(),
            "data/tier-pavement-debt-budget.csv".to_string(),
        );
    }

    if let Some(rollup) = index.by_route.get(&canonical_route_key(route)) {
        return (
            rollup.total_debt_cost_m,
            join_string_set(&rollup.debt_classes),
            format!(
                "route-level pavement debt rollup across {} bundle(s) pending candidate bundle materialization",
                rollup.affected_bundles.len()
            ),
            "data/tier-pavement-debt-budget.csv".to_string(),
        );
    }

    (
        0.0,
        "none".to_string(),
        "no pavement debt row joined".to_string(),
        String::new(),
    )
}

fn print_tier_pavement_debt_budget_summary(
    output: &Path,
    rows: &[TierPavementDebtBudgetRow],
    details: bool,
) {
    let total_cost_m = rows.iter().map(|row| row.total_debt_cost_m).sum::<f64>();
    let mut by_class = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *by_class.entry(row.debt_class.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} pavement debt budget rows to {}",
        rows.len(),
        output.display()
    );
    println!("  planning pavement debt: ${total_cost_m:.2}M");
    for (debt_class, count) in by_class {
        println!("  {debt_class}: {count}");
    }

    if details {
        println!();
        println!(
            "{:<4} {:<8} {:<18} {:>7} {:>10} {}",
            "Tier", "Route", "Debt", "Members", "Cost $M", "Bundle"
        );
        println!("{}", "-".repeat(104));
        for row in rows {
            println!(
                "{:<4} {:<8} {:<18} {:>7} {:>10.2} {}",
                row.tier,
                row.route,
                row.debt_class,
                row.blocked_member_count,
                row.total_debt_cost_m,
                row.segment_bundle_id
            );
        }
    }
}

// `tier_pavement_debt_budget_gate_failures` moved to `tier_pavement_debt_budget_gate_failures.rs`

#[derive(Default)]
struct TierPavementAcquisitionBuilder {
    state: String,
    tiers: std::collections::BTreeSet<String>,
    routes: std::collections::BTreeSet<String>,
    bundles: std::collections::BTreeSet<String>,
    blocked_member_count: usize,
}

fn tier_pavement_acquisition_plan_rows(
    gap_rows: &[TierPavementSourceGapRow],
) -> Vec<TierPavementAcquisitionPlanRow> {
    let mut builders = std::collections::BTreeMap::<String, TierPavementAcquisitionBuilder>::new();

    for row in gap_rows {
        let states = row
            .affected_states
            .split(';')
            .map(str::trim)
            .filter(|state| !state.is_empty())
            .collect::<Vec<_>>();
        let member_share = if states.is_empty() {
            row.blocker_count
        } else {
            row.blocker_count.div_ceil(states.len())
        };
        for state in states {
            let builder = builders.entry(state.to_string()).or_insert_with(|| {
                TierPavementAcquisitionBuilder {
                    state: state.to_string(),
                    ..Default::default()
                }
            });
            builder.tiers.insert(row.tier.clone());
            builder.routes.insert(row.route.clone());
            builder.bundles.insert(row.segment_bundle_id.clone());
            builder.blocked_member_count += member_share;
        }
    }

    builders
        .into_values()
        .map(|builder| {
            let affected_routes = join_string_set(&builder.routes);
            let affected_bundles = join_string_set(&builder.bundles);
            let tier = join_string_set(&builder.tiers);
            let (source_priority, acquisition_action) =
                pavement_acquisition_action(builder.routes.len(), builder.blocked_member_count);
            TierPavementAcquisitionPlanRow {
                state: builder.state,
                tier,
                source_family: "HPMS IRI plus state pavement condition feed".to_string(),
                route_count: builder.routes.len(),
                affected_routes,
                bundle_count: builder.bundles.len(),
                affected_bundles,
                blocked_member_count: builder.blocked_member_count,
                source_priority: source_priority.to_string(),
                acquisition_action: acquisition_action.to_string(),
                required_fields:
                    "route id; segment geometry or linear reference; IRI or condition score; observation year; source owner"
                        .to_string(),
                next_artifact: "data/tier-pavement-docket.csv".to_string(),
                optimizer_effect:
                    "populate member pavement evidence so held T2 bundles can pass or become repair rows"
                        .to_string(),
                validation_status: "review".to_string(),
            }
        })
        .collect()
}

fn pavement_acquisition_action(
    route_count: usize,
    blocked_member_count: usize,
) -> (&'static str, &'static str) {
    if route_count >= 3 || blocked_member_count >= 80 {
        (
            "A",
            "refresh HPMS/state pavement feed for broad multi-route coverage",
        )
    } else if route_count == 2 || blocked_member_count >= 30 {
        (
            "B",
            "refresh HPMS/state pavement feed for targeted corridor coverage",
        )
    } else {
        (
            "C",
            "fill targeted pavement rows from HPMS or state DOT asset feed",
        )
    }
}

