fn t4_terminal_contact_proof_artifact_contract_gate_failures(
    rows: &[T4TerminalContactProofArtifactContractRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no terminal contact proof artifact contract rows emitted".to_string());
        return failures;
    }
    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.contract_id.trim().is_empty()
            || row.source_family.trim().is_empty()
            || row.accepted_proof_status.trim().is_empty()
            || row.required_fields.trim().is_empty()
            || row.allowed_artifact_modes.trim().is_empty()
            || row.prohibited_sources.trim().is_empty()
            || row.promotion_rule.trim().is_empty()
            || row.source_needed_decision.trim().is_empty()
            || row.blocked_decision.trim().is_empty()
            || row.rejected_decision.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete contract fields",
                row.contract_id
            ));
        }
        if !seen.insert(row.contract_id.clone()) {
            failures.push(format!("{} appears more than once", row.contract_id));
        }
        if row.source_family != "public-terminal-contact-proof" {
            failures.push(format!(
                "{} has unsupported source family {}",
                row.contract_id, row.source_family
            ));
        }
        if row.accepted_proof_status != "source-backed" {
            failures.push(format!(
                "{} does not define source-backed acceptance",
                row.contract_id
            ));
        }
        for required in [
            "route",
            "terminal district",
            "route-to-terminal contact statement",
            "source title",
            "source url or cached artifact",
            "capture date",
            "selected higher-tier attachment",
            "validation decision",
        ] {
            if !row.required_fields.contains(required) {
                failures.push(format!(
                    "{} missing required proof field {}",
                    row.contract_id, required
                ));
            }
        }
        for mode in ["manual-citation", "cached-source-artifact"] {
            if !row.allowed_artifact_modes.contains(mode) {
                failures.push(format!(
                    "{} missing allowed artifact mode {}",
                    row.contract_id, mode
                ));
            }
        }
        for prohibited in [
            "data/intermodal_terminals.csv",
            "terminal district seed",
            "route proximity",
            "district membership",
        ] {
            if !row.prohibited_sources.contains(prohibited) {
                failures.push(format!(
                    "{} missing prohibited source {}",
                    row.contract_id, prohibited
                ));
            }
        }
        if !row.promotion_rule.contains("non-seed source artifact")
            || !row
                .promotion_rule
                .contains("route terminal district contact statement")
        {
            failures.push(format!(
                "{} promotion rule does not require non-seed route contact proof",
                row.contract_id
            ));
        }
        if !row.source_needed_decision.contains("source-needed")
            || !row.blocked_decision.contains("blocked")
            || !row.rejected_decision.contains("rejected")
        {
            failures.push(format!(
                "{} does not preserve unresolved/rejected decision states",
                row.contract_id
            ));
        }
        if row.validation_status != "pass" {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.contract_id, row.validation_status
            ));
        }
    }
    failures
}

fn t4_terminal_contact_proof_source_registry_rows(
    proof_rows: &[T4TerminalContactProofDocketRow],
    accepted_source_rows: &[T4TerminalContactAcceptedProofSourceRow],
) -> Vec<T4TerminalContactProofSourceRegistryRow> {
    let accepted_by_queue = accepted_source_rows
        .iter()
        .filter(|row| row.validation_status == "pass")
        .map(|row| (row.queue_id.as_str(), row))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut rows = proof_rows
        .iter()
        .map(|row| {
            if let Some(accepted) = accepted_by_queue.get(row.queue_id.as_str()) {
                T4TerminalContactProofSourceRegistryRow {
                    registry_id: format!("T4CONTACTREGISTRY-{}", stable_id_fragment(&row.queue_id)),
                    task_id: row.task_id.clone(),
                    queue_id: row.queue_id.clone(),
                    route: row.route.clone(),
                    terminal_district: row.terminal_district.clone(),
                    source_family: row.source_family.clone(),
                    source_artifact_mode: accepted.source_artifact_mode.clone(),
                    source_title: accepted.source_title.clone(),
                    source_url_or_cache_artifact: accepted.source_url_or_cache_artifact.clone(),
                    capture_date: accepted.capture_date.clone(),
                    contact_statement_status: "source-backed".to_string(),
                    selected_higher_tier_attachment_status: "attached".to_string(),
                    registry_status: "source-backed".to_string(),
                    proof_source_artifact: accepted.proof_source_artifact.clone(),
                    registry_blocker: "none".to_string(),
                    contract_artifact: "data/t4-terminal-contact-proof-artifact-contract.csv"
                        .to_string(),
                    next_artifact:
                        "waves/2026-05-13-terminal-contact-source-acquisition-spine/plans/pulse-03.md"
                            .to_string(),
                    validation_status: "pass".to_string(),
                }
            } else {
                T4TerminalContactProofSourceRegistryRow {
                    registry_id: format!("T4CONTACTREGISTRY-{}", stable_id_fragment(&row.queue_id)),
                    task_id: row.task_id.clone(),
                    queue_id: row.queue_id.clone(),
                    route: row.route.clone(),
                    terminal_district: row.terminal_district.clone(),
                    source_family: row.source_family.clone(),
                    source_artifact_mode: "source-needed".to_string(),
                    source_title: "source-needed".to_string(),
                    source_url_or_cache_artifact: "source-needed".to_string(),
                    capture_date: "source-needed".to_string(),
                    contact_statement_status: "source-needed".to_string(),
                    selected_higher_tier_attachment_status: "source-needed".to_string(),
                    registry_status: "source-needed".to_string(),
                    proof_source_artifact: "source-needed".to_string(),
                    registry_blocker:
                        "manual citation or cached source artifact not registered for route-to-terminal contact proof"
                            .to_string(),
                    contract_artifact: "data/t4-terminal-contact-proof-artifact-contract.csv"
                        .to_string(),
                    next_artifact:
                        "waves/2026-05-13-terminal-contact-source-acquisition-spine/plans/pulse-03.md"
                            .to_string(),
                    validation_status: "review".to_string(),
                }
            }
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        left.terminal_district
            .cmp(&right.terminal_district)
            .then(left.route.cmp(&right.route))
    });
    rows
}

