fn t4_terminal_columbus_proof_attempt_gate_failures(
    rows: &[T4TerminalColumbusProofAttemptRow],
    source_access_rows: &[T4TerminalColumbusSourceAccessRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    let expected_ids = source_access_rows
        .iter()
        .map(|row| row.queue_id.as_str())
        .collect::<std::collections::BTreeSet<_>>();

    if rows.is_empty() {
        failures.push("no Columbus South proof attempt rows emitted".to_string());
        return failures;
    }
    if rows.len() != expected_ids.len() {
        failures.push(format!(
            "Columbus proof attempts have {} rows but expected {} source access rows",
            rows.len(),
            expected_ids.len()
        ));
    }

    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.attempt_id.trim().is_empty()
            || row.access_id.trim().is_empty()
            || row.intake_id.trim().is_empty()
            || row.queue_id.trim().is_empty()
            || row.route.trim().is_empty()
            || row.terminal_district.trim().is_empty()
            || row.source_family.trim().is_empty()
            || row.source_artifact.trim().is_empty()
            || row.capture_status.trim().is_empty()
            || row.contact_statement_status.trim().is_empty()
            || row.selected_higher_tier_attachment_status.trim().is_empty()
            || row.proof_attempt_status.trim().is_empty()
            || row.proof_decision.trim().is_empty()
            || row.proof_blocker.trim().is_empty()
            || row.next_artifact.trim().is_empty()
            || row.validation_status.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete proof attempt fields",
                row.attempt_id
            ));
        }
        if !seen.insert(row.queue_id.clone()) {
            failures.push(format!(
                "{} appears more than once in Columbus proof attempts",
                row.queue_id
            ));
        }
        if row.terminal_district != "Columbus South" {
            failures.push(format!(
                "{} is not a Columbus South proof attempt row",
                row.queue_id
            ));
        }
        if !expected_ids.contains(row.queue_id.as_str()) {
            failures.push(format!(
                "{} does not appear in Columbus source access",
                row.queue_id
            ));
        }
        if !matches!(
            row.proof_attempt_status.as_str(),
            "accepted" | "source-needed" | "blocked" | "rejected"
        ) {
            failures.push(format!(
                "{} has invalid proof attempt status {}",
                row.queue_id, row.proof_attempt_status
            ));
        }
        if row.proof_attempt_status == "accepted" {
            if row.source_artifact == "source-needed"
                || row.contact_statement_status != "source-backed"
                || row.selected_higher_tier_attachment_status != "attached"
                || row.proof_decision != "source-backed"
                || row.validation_status != "pass"
            {
                failures.push(format!(
                    "{} accepted proof attempt lacks non-seed proof evidence",
                    row.queue_id
                ));
            }
        } else if row.source_artifact != "source-needed"
            || row.contact_statement_status != "source-needed"
            || row.selected_higher_tier_attachment_status != "source-needed"
            || row.validation_status != "review"
        {
            failures.push(format!(
                "{} unresolved proof attempt must remain source-needed/review",
                row.queue_id
            ));
        }
        if row.proof_attempt_status == "blocked"
            && !row
                .proof_blocker
                .contains("no safe live terminal-contact fetch command")
        {
            failures.push(format!(
                "{} blocked proof attempt lacks source-access blocker",
                row.queue_id
            ));
        }
    }

    for expected_id in expected_ids {
        if !seen.contains(expected_id) {
            failures.push(format!(
                "{expected_id} is missing from Columbus proof attempts"
            ));
        }
    }

    failures
}

fn t4_terminal_scenario_readiness_rows(
    contact_rows: &[T4TerminalContactEvidenceRow],
) -> Vec<T4TerminalScenarioReadinessRow> {
    let mut rows = contact_rows
        .iter()
        .filter(|row| matches!(row.decision.as_str(), "source-backed" | "scenario-ready"))
        .map(|row| T4TerminalScenarioReadinessRow {
            docket_id: format!("T4SCENARIO-{}", stable_id_fragment(&row.queue_id)),
            route: row.route.clone(),
            zone_id: row.zone_id.clone(),
            terminal_district: row.terminal_district_seed.clone(),
            contact_basis: row.contact_basis.clone(),
            contact_proof_source: row.contact_proof_source.clone(),
            selected_higher_tier_attachment: row.selected_higher_tier_attachment.clone(),
            freight_access_rationale: terminal_scenario_rationale(row),
            scenario_decision: if row.decision == "scenario-ready" {
                "scenario-candidate".to_string()
            } else {
                "source-backed-review".to_string()
            },
            scenario_artifact: if row.decision == "scenario-ready" {
                "data/t4-terminal-scenario-readiness.csv".to_string()
            } else {
                String::new()
            },
            source_evidence_status: row.evidence_status.clone(),
            release_status: "held-source-review".to_string(),
            next_artifact: "waves/2026-05-13-t4-terminal-contact-evidence/plans/pulse-05.md"
                .to_string(),
            validation_status: if row.decision == "scenario-ready" {
                "review".to_string()
            } else {
                "held".to_string()
            },
        })
        .collect::<Vec<_>>();

    if rows.is_empty() {
        rows.push(T4TerminalScenarioReadinessRow {
            docket_id: "__all_t4_terminal_scenarios__".to_string(),
            route: String::new(),
            zone_id: "all-terminal-contact-zones".to_string(),
            terminal_district: String::new(),
            contact_basis: "no-source-backed-terminal-contact-rows".to_string(),
            contact_proof_source: String::new(),
            selected_higher_tier_attachment: String::new(),
            freight_access_rationale:
                "scenario docket remains empty until a contact row is source-backed".to_string(),
            scenario_decision: "no-source-backed-contacts".to_string(),
            scenario_artifact: String::new(),
            source_evidence_status: "source-needed".to_string(),
            release_status: "held-source-needed".to_string(),
            next_artifact: "data/t4-terminal-contact-evidence.csv".to_string(),
            validation_status: "held".to_string(),
        });
    }

    rows.sort_by(|a, b| {
        a.scenario_decision
            .cmp(&b.scenario_decision)
            .then_with(|| a.zone_id.cmp(&b.zone_id))
            .then_with(|| a.route.cmp(&b.route))
    });
    rows
}

fn terminal_scenario_rationale(row: &T4TerminalContactEvidenceRow) -> String {
    format!(
        "source-backed contact between {} and {}; preserves T4 access while selecting scenario scope",
        row.route, row.terminal_district_seed
    )
}

