fn t4_terminal_scenario_readiness_gate_failures(
    rows: &[T4TerminalScenarioReadinessRow],
    contact_rows: &[T4TerminalContactEvidenceRow],
) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T4 terminal scenario readiness rows emitted".to_string());
        return failures;
    }

    let source_backed_count = contact_rows
        .iter()
        .filter(|row| matches!(row.decision.as_str(), "source-backed" | "scenario-ready"))
        .count();
    if source_backed_count == 0
        && !rows.iter().any(|row| {
            row.docket_id == "__all_t4_terminal_scenarios__"
                && row.scenario_decision == "no-source-backed-contacts"
                && row.release_status == "held-source-needed"
        })
    {
        failures.push("empty scenario docket lacks held clear row".to_string());
    }

    let mut seen = std::collections::BTreeSet::<String>::new();
    for row in rows {
        if row.docket_id.trim().is_empty()
            || row.zone_id.trim().is_empty()
            || row.contact_basis.trim().is_empty()
            || row.freight_access_rationale.trim().is_empty()
            || row.scenario_decision.trim().is_empty()
            || row.source_evidence_status.trim().is_empty()
            || row.release_status.trim().is_empty()
            || row.next_artifact.trim().is_empty()
        {
            failures.push(format!(
                "{} has incomplete scenario docket fields",
                row.docket_id
            ));
        }
        if !seen.insert(row.docket_id.clone()) {
            failures.push(format!("{} is duplicated", row.docket_id));
        }
        if matches!(
            row.scenario_decision.as_str(),
            "scenario-candidate" | "source-backed-review"
        ) && (row.route.trim().is_empty()
            || row.terminal_district.trim().is_empty()
            || row.contact_proof_source.trim().is_empty()
            || row.selected_higher_tier_attachment.trim().is_empty()
            || row.source_evidence_status != "accepted")
        {
            failures.push(format!(
                "{} scenario row lacks proof, terminal, attachment, or accepted evidence",
                row.docket_id
            ));
        }
        if row.scenario_decision == "scenario-candidate" && row.scenario_artifact.trim().is_empty()
        {
            failures.push(format!(
                "{} scenario candidate lacks artifact",
                row.docket_id
            ));
        }
        if row.release_status != "held-source-review" && row.release_status != "held-source-needed"
        {
            failures.push(format!(
                "{} has invalid release status {}",
                row.docket_id, row.release_status
            ));
        }
        if !matches!(row.validation_status.as_str(), "review" | "held") {
            failures.push(format!(
                "{} has invalid validation status {}",
                row.docket_id, row.validation_status
            ));
        }
    }
    failures
}

fn t3_t4_access_gap_rows(
    route_rows: &[T3ZoneRouteColumnRow],
    terminal_rows: &[T4TerminalAccessColumnRow],
) -> Vec<T3T4AccessGapRow> {
    let mut rows = Vec::new();

    for row in route_rows
        .iter()
        .filter(|row| row.next_artifact == "data/t3-t4-access-gaps.csv")
    {
        let (gap_class, repair_action) = match row.column_decision.as_str() {
            "review" => (
                "below-threshold-feeder",
                "prove-terminal-evidence-or-keep-t4",
            ),
            _ => ("route-column-review", "review-route-column-disposition"),
        };
        rows.push(T3T4AccessGapRow {
            gap_id: format!(
                "T3GAP-{}-{}",
                canonical_route_key(&row.zone_id),
                canonical_route_key(&row.route)
            ),
            source_surface: "t3-zone-route-columns".to_string(),
            route: row.route.clone(),
            zone_id: row.zone_id.clone(),
            current_score: row.current_score,
            constraint_adjusted_score: row.constraint_adjusted_score,
            hard_blocker_count: row.hard_blocker_count,
            claim_blocker_count: row.claim_blocker_count,
            constraint_debt_cost_m: row.constraint_debt_cost_m,
            lifecycle_debt_cost_m: row.lifecycle_debt_cost_m,
            constraint_penalty_score: row.constraint_penalty_score,
            top_constraint_classes: row.top_constraint_classes.clone(),
            constraint_ledger_artifact: row.constraint_ledger_artifact.clone(),
            promise_horizon_hours: row.promise_horizon_hours,
            gap_class: gap_class.to_string(),
            gap_reason: row.selection_basis.clone(),
            required_evidence: row.contact_requirement.clone(),
            repair_action: repair_action.to_string(),
            next_artifact: "data/t3-zone-map-diagnostics.csv".to_string(),
            upward_pressure_allowed: false,
            validation_status: "review".to_string(),
        });
    }

    for row in terminal_rows
        .iter()
        .filter(|row| row.next_artifact == "data/t3-t4-access-gaps.csv")
    {
        let (gap_class, repair_action) = match row.column_decision.as_str() {
            "zone-assignment-needed" => {
                ("zone-assignment-needed", "assign-zone-or-terminal-district")
            }
            "terminal-review" => (
                "terminal-evidence-needed",
                "prove-terminal-access-or-keep-local",
            ),
            _ => (
                "terminal-column-review",
                "review-terminal-column-disposition",
            ),
        };
        rows.push(T3T4AccessGapRow {
            gap_id: format!(
                "T4GAP-{}-{}",
                canonical_route_key(&row.zone_id),
                canonical_route_key(&row.route)
            ),
            source_surface: "t4-terminal-access-columns".to_string(),
            route: row.route.clone(),
            zone_id: row.zone_id.clone(),
            current_score: row.current_score,
            constraint_adjusted_score: row.constraint_adjusted_score,
            hard_blocker_count: row.hard_blocker_count,
            claim_blocker_count: row.claim_blocker_count,
            constraint_debt_cost_m: row.constraint_debt_cost_m,
            lifecycle_debt_cost_m: row.lifecycle_debt_cost_m,
            constraint_penalty_score: row.constraint_penalty_score,
            top_constraint_classes: row.top_constraint_classes.clone(),
            constraint_ledger_artifact: row.constraint_ledger_artifact.clone(),
            promise_horizon_hours: row.promise_horizon_hours,
            gap_class: gap_class.to_string(),
            gap_reason: row.selection_basis.clone(),
            required_evidence: row.evidence_required.clone(),
            repair_action: repair_action.to_string(),
            next_artifact: if row.column_decision == "terminal-review" {
                "data/t4-terminal-contact-evidence.csv".to_string()
            } else {
                "data/t3-zone-map-diagnostics.csv".to_string()
            },
            upward_pressure_allowed: false,
            validation_status: "review".to_string(),
        });
    }

    rows.sort_by(|a, b| {
        a.gap_class
            .cmp(&b.gap_class)
            .then_with(|| a.zone_id.cmp(&b.zone_id))
            .then_with(|| b.current_score.total_cmp(&a.current_score))
            .then_with(|| a.route.cmp(&b.route))
            .then_with(|| a.source_surface.cmp(&b.source_surface))
    });
    rows
}

