fn t1_stop_selector_gate_failures(rows: &[T1StopSelectorRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T1 stop selector rows emitted".to_string());
        return failures;
    }
    let mut by_route = std::collections::BTreeMap::<&str, Vec<&T1StopSelectorRow>>::new();
    for row in rows {
        by_route.entry(row.route.as_str()).or_default().push(row);
        if row.selector_weight <= 0 {
            failures.push(format!(
                "{}:{} has non-positive selector weight",
                row.route, row.stop_id
            ));
        }
        if !row.validation_status.eq_ignore_ascii_case("pass") {
            failures.push(format!(
                "{}:{} has validation_status={}",
                row.route, row.stop_id, row.validation_status
            ));
        }
    }
    for (route, route_rows) in by_route {
        if route_rows.len() < 3 {
            failures.push(format!("{route}: fewer than 3 selected stops"));
        }
        let regions = route_rows
            .iter()
            .map(|row| row.metis_region)
            .collect::<std::collections::BTreeSet<_>>();
        if regions.len() != route_rows[0].target_regions {
            failures.push(format!(
                "{route}: expected {} METIS regions, found {}",
                route_rows[0].target_regions,
                regions.len()
            ));
        }
    }
    failures
}

fn load_t1_stop_selector(path: &Path) -> Result<Vec<T1StopSelectorInputRow>> {
    let mut reader = csv::Reader::from_path(path)?;
    let mut rows = Vec::new();
    for row in reader.deserialize() {
        rows.push(row?);
    }
    Ok(rows)
}

fn t1_beck_alignment_rows(stop_rows: &[T1StopSelectorInputRow]) -> Vec<T1BeckAlignmentRow> {
    let diagnostics = route_map::beck_t1_diagnostics()
        .into_iter()
        .map(|row| (normalise_designation(row.corridor), row))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut by_route = std::collections::BTreeMap::<String, Vec<&T1StopSelectorInputRow>>::new();
    for row in stop_rows {
        by_route
            .entry(normalise_designation(&row.route))
            .or_default()
            .push(row);
    }

    by_route
        .into_iter()
        .map(|(route, rows)| {
            let diagnostic = diagnostics.get(&route);
            let selector_stop_count = rows.len();
            let selector_boundary_count = rows.iter().filter(|row| row.boundary_after).count();
            let selector_regions = rows
                .iter()
                .map(|row| row.metis_region)
                .collect::<std::collections::BTreeSet<_>>()
                .len();
            let (beck_stop_count, beck_drawn_stop_count, beck_transfer_stop_count) = diagnostic
                .map_or((0, 0, 0), |row| {
                    (
                        row.stop_count,
                        row.drawn_stop_count,
                        row.transfer_stop_count,
                    )
                });
            let alignment_status = if diagnostic.is_none() {
                "missing-beck-route"
            } else if beck_stop_count < selector_stop_count {
                "beck-under-covers-selector"
            } else if diagnostic
                .map(|row| row.review_flag != "ok")
                .unwrap_or(false)
            {
                "aligned-with-policy-review"
            } else {
                "aligned"
            };
            T1BeckAlignmentRow {
                route,
                selector_stop_count,
                selector_boundary_count,
                selector_regions,
                beck_stop_count,
                beck_drawn_stop_count,
                beck_transfer_stop_count,
                beck_action: diagnostic
                    .map(|row| row.service_action.to_string())
                    .unwrap_or_else(|| "missing-diagnostic".to_string()),
                beck_review_flag: diagnostic
                    .map(|row| row.review_flag.to_string())
                    .unwrap_or_else(|| "missing-diagnostic".to_string()),
                alignment_status: alignment_status.to_string(),
                validation_status: if matches!(
                    alignment_status,
                    "aligned" | "aligned-with-policy-review"
                ) {
                    "pass"
                } else {
                    "review"
                }
                .to_string(),
            }
        })
        .collect()
}

fn write_t1_beck_alignment(path: &Path, rows: &[T1BeckAlignmentRow]) -> Result<()> {
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    let mut writer = csv::Writer::from_path(path)?;
    for row in rows {
        writer.serialize(row)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_t1_beck_alignment_summary(output: &Path, rows: &[T1BeckAlignmentRow]) {
    let mut counts = std::collections::BTreeMap::<&str, usize>::new();
    for row in rows {
        *counts.entry(row.alignment_status.as_str()).or_default() += 1;
    }
    println!(
        "  wrote {} alignment rows to {}",
        rows.len(),
        output.display()
    );
    for (status, count) in counts {
        println!("  {status}: {count}");
    }
}

fn t1_beck_alignment_gate_failures(rows: &[T1BeckAlignmentRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.is_empty() {
        failures.push("no T1 Beck alignment rows emitted".to_string());
        return failures;
    }
    for row in rows {
        if !row.validation_status.eq_ignore_ascii_case("pass") {
            failures.push(format!(
                "{} alignment_status={} selector_stops={} beck_stops={}",
                row.route, row.alignment_status, row.selector_stop_count, row.beck_stop_count
            ));
        }
    }
    failures
}

#[derive(Debug, Clone)]
struct T1DesignReviewRow {
    route: String,
    selected: bool,
    design_role: &'static str,
    promise_count: usize,
    selected_stop_count: usize,
    top_city_stop_count: usize,
    selector_reason: String,
    beck_action: String,
    beck_review_flag: String,
    overlap_corridors: String,
    design_status: &'static str,
    next_design_action: &'static str,
}

fn t1_design_review_rows(selector_rows: &[T1LineSelectorRow]) -> Vec<T1DesignReviewRow> {
    let diagnostics = route_map::beck_t1_diagnostics()
        .into_iter()
        .map(|row| (normalise_designation(row.corridor), row))
        .collect::<std::collections::BTreeMap<_, _>>();

    selector_rows
        .iter()
        .filter(|row| {
            row.selected
                || row.sla_pair_count > 0
                || row.decision == "reject-score-exception"
                || row.decision == "reject-route-budget"
                || row.decision == "reject-stop-budget"
        })
        .map(|row| {
            let diagnostic = diagnostics.get(&row.route);
            let beck_action = diagnostic
                .map(|diag| diag.service_action.to_string())
                .unwrap_or_else(|| "missing-diagnostic".to_string());
            let beck_review_flag = diagnostic
                .map(|diag| diag.review_flag.to_string())
                .unwrap_or_else(|| "missing-diagnostic".to_string());
            let overlap_corridors = diagnostic
                .map(|diag| diag.shared_segment_corridors.clone())
                .unwrap_or_default();
            let design_role = if row.selected && row.sla_pair_count > 0 {
                "promise-spine"
            } else if row.selected {
                "score-backbone-exception"
            } else if row.decision == "reject-score-exception" {
                "score-backbone-demoted"
            } else if row.sla_pair_count > 0 {
                "unmet-promise-blocker"
            } else {
                "cutline-candidate"
            };
            let explicit_score_exception_keep = matches!(
                row.reason,
                "score-exception-keep" | "score-exception-conditional-keep"
            );
            let design_status = if !row.selected {
                "held"
            } else if diagnostic.is_none()
                || (row.sla_pair_count == 0 && !explicit_score_exception_keep)
                || beck_review_flag != "ok"
            {
                "policy-review"
            } else {
                "accepted"
            };
            let next_design_action = if !row.selected && row.sla_pair_count > 0 {
                "raise-budget-or-recut-promises"
            } else if row.decision == "reject-score-exception" {
                "score-exception-demoted"
            } else if !row.selected {
                "hold-outside-current-budget"
            } else if diagnostic.is_none() {
                "add-beck-diagnostic-row"
            } else if row.sla_pair_count == 0 && !explicit_score_exception_keep {
                "justify-as-national-relay-or-demote-to-t2"
            } else if beck_review_flag != "ok" {
                "resolve-shared-segment-map-policy"
            } else {
                "keep-in-t1-design"
            };

            T1DesignReviewRow {
                route: row.route.clone(),
                selected: row.selected,
                design_role,
                promise_count: row.sla_pair_count,
                selected_stop_count: row.selected_stop_count,
                top_city_stop_count: row.top_city_stop_count,
                selector_reason: row.reason.to_string(),
                beck_action,
                beck_review_flag,
                overlap_corridors,
                design_status,
                next_design_action,
            }
        })
        .collect()
}

fn build_t1_design_review_csv(rows: &[T1DesignReviewRow]) -> String {
    let mut csv = String::from(
        "route,selected,design_role,promise_count,selected_stop_count,top_city_stop_count,selector_reason,beck_action,beck_review_flag,overlap_corridors,design_status,next_design_action\n",
    );
    for row in rows {
        push_csv_line(
            &mut csv,
            &[
                &row.route,
                if row.selected { "true" } else { "false" },
                row.design_role,
                &row.promise_count.to_string(),
                &row.selected_stop_count.to_string(),
                &row.top_city_stop_count.to_string(),
                &row.selector_reason,
                &row.beck_action,
                &row.beck_review_flag,
                &row.overlap_corridors,
                row.design_status,
                row.next_design_action,
            ],
        );
    }
    csv
}

fn t1_design_review_gate_failures(rows: &[T1DesignReviewRow]) -> Vec<String> {
    let mut failures = Vec::new();
    if rows.iter().all(|row| !row.selected) {
        failures.push("no selected T1 design rows".to_string());
    }
    for row in rows {
        if row.selected && row.selected_stop_count == 0 {
            failures.push(format!("{} selected without stop chain", row.route));
        }
        if !row.selected && row.promise_count > 0 {
            failures.push(format!(
                "{} carries {} promise pairs but is not selected",
                row.route, row.promise_count
            ));
        }
    }
    failures
}

